import { cn } from "@/lib/utils"

type Medium = "web" | "slide"
type SlideQuoteCopy = { quote: string; attribution: string; title?: string }

export function SlideQuote({ copy, medium = "web" }: { copy: SlideQuoteCopy; medium?: Medium }) {
  const slide = medium === "slide"
  return (
    <figure data-slot="slide-quote" data-medium={medium} className={cn("flex flex-col justify-center gap-10 bg-muted text-foreground", slide ? "aspect-video w-full overflow-hidden px-32 py-20" : "px-6 py-20 md:px-12")}>
      <blockquote className={cn("max-w-5xl border-l-4 border-primary pl-10 font-heading font-medium tracking-tight", slide ? "text-6xl" : "text-2xl md:text-3xl")}>{copy.quote}</blockquote>
      <figcaption className={cn("flex flex-col gap-1 pl-10", slide ? "text-2xl" : "text-base")}>
        <span className="font-semibold">{copy.attribution}</span>
        {copy.title ? <span className="text-muted-foreground">{copy.title}</span> : null}
      </figcaption>
    </figure>
  )
}
